def main(keys_path, tr_dir):
    keys = open(keys_path, encoding='utf-8').read().split('\n')
    for eng in T:
        if eng not in keys:
            keys.append(eng)
    open(keys_path, 'w', encoding='utf-8').write('\n'.join(keys))
    for ci, code in enumerate(CODES):
        path = os.path.join(tr_dir, code + '.txt')
        lines = [l for l in open(path, encoding='utf-8').read().split('\n') if l.strip()]
        rows = [l.partition('\t')[2] for l in lines]
        while len(rows) < len(keys):
            rows.append('=')
        for eng, tr in T.items():
            rows[keys.index(eng)] = tr[ci].replace('"', '\\"')
        open(path, 'w', encoding='utf-8').write(''.join(f'{i}\t{t}\n' for i, t in enumerate(rows)))
main(sys.argv[1], sys.argv[2])
